import{describe,it,expect,beforeEach,vi}from"vitest";describe("Glossary search and stats helpers",()=>{let e;beforeEach(()=>{e=[{id:"dynasty",term:"Dynasty",category:"History",tags:["empire"]},{id:"ikat",term:"Ikat",category:"Culture",tags:["weaving"]}]}),it("correctly counts glossary terms and categories",()=>{const t=e.length,r=[...new Set(e.map(e=>e.category))].length;expect(t).toBe(2),expect(r).toBe(2)})});